-- Ursula Underwood (profileID=21) — ENDORSEMENTS
-- Generated by endorsement_framework.py

-- STEP 1: PHRASE_ENDORSE rows for all Ursula Underwood phrasings

SELECT p.argumentID, p.phrasingID, 21, 100, 1
FROM PHRASING p
WHERE p.coinedBy = 21
  AND NOT EXISTS (
    SELECT 1 FROM PHRASE_ENDORSE pe
    WHERE pe.profileID = 21 AND pe.argumentID = p.argumentID
  );

-- STEP 2: Endorsement chains (Because / Therefore / Rebuttal)

DELETE FROM ENDORSEMENT WHERE profileID=21 AND targArgID IN (107,110,124,125,126,127,128,129,130,134,135,136,142,143,144,161,192,288,291,293,295,297,298,315,316,322,323,400,401,412,428,543,544,546,551,560,561,601,604,606,607,651,652,672,777,785,791,793,795,797,800,801,844,849,901,902,910,920,958,964,977,1312,1345,1347,1351,1385,1386,1387,1425,1440,1614);


-- STEP 3: Sync PHRASE_ENDORSE active flag with opinion acceptance

UPDATE PHRASE_ENDORSE pe
JOIN OPINION o ON pe.argumentID = o.argumentID AND o.profileID = 21
SET pe.active = o.acceptance
WHERE pe.profileID = 21;

SELECT 'Done: endorsements for profileID=21' AS status;